<script setup>
import { computed, ref } from 'vue';
import { useForm } from '@inertiajs/vue3';
const props = defineProps({ record: Object, checklist: Array, review: Boolean, driver: Boolean });
const emit = defineEmits(['revise']);
const expanded = ref(false), reviewAction = ref(null), cancelPrompt = ref(false);
const reviewForm = useForm({ status: 'APPROVED', reason: '' });
const startForm = useForm({ go_no_go_id: props.record.id, report_ids: props.record.units.map(unit => unit.id) });
const cancelForm = useForm({});
const plates = computed(() => props.record.units.map(unit => unit.vehicle_plate).join(', '));
const names = computed(() => props.record.units.map(unit => unit.driver_name).join(', '));
const canStart = computed(() => props.driver && props.record.status === 'APPROVED' && props.record.driver_decision === 'LAIK' && !props.record.started_at);
const canRevise = computed(() => props.driver && !props.record.started_at && (['REJECTED', 'CANCELLED'].includes(props.record.status) || (props.record.status === 'APPROVED' && props.record.driver_decision === 'TIDAK_LAIK')));
const date = value => value ? new Date(value).toLocaleString('id-ID', { timeZone: 'Asia/Makassar', dateStyle: 'medium', timeStyle: 'short' }) + ' WITA' : '-';
const choose = status => { reviewForm.reset(); reviewForm.clearErrors(); reviewForm.status = status; reviewAction.value = status; };
const submitReview = () => reviewForm.patch(`/coordinator/go-no-go/${props.record.id}/review`, { preserveScroll: true, onSuccess: () => { reviewAction.value = null; } });
const start = () => startForm.post('/driver/escort-batches', { preserveScroll: true });
const cancel = () => cancelForm.post(`/driver/go-no-go/${props.record.id}/cancel`, { preserveScroll: true, onSuccess: () => { cancelPrompt.value = false; } });
</script>

<template>
    <article class="min-w-0 rounded-2xl border border-slate-200 bg-white p-4">
        <header class="flex flex-wrap items-start justify-between gap-3"><div class="min-w-0 flex-1"><p class="text-xs font-bold uppercase text-slate-500">GO/NO GO · Revisi {{ record.revision }} · {{ record.units.length }} unit</p><h3 class="mt-1 break-words font-bold text-slate-900">{{ record.escorter_name }} / {{ record.nik }}</h3><p class="mt-1 line-clamp-2 break-words text-sm text-slate-600" :title="plates">{{ plates }}</p><p class="mt-1 text-xs text-slate-500">Dikirim {{ date(record.submitted_at) }}</p><span class="mt-2 inline-flex rounded-lg px-3 py-1.5 text-xs font-bold" :class="record.result === 'GO' ? 'bg-lime-100 text-lime-900' : record.status === 'PENDING' ? 'bg-amber-50 text-amber-800' : 'bg-red-50 text-red-800'">{{ record.started_at ? 'Escort sudah dimulai' : record.status === 'CANCELLED' ? 'Dibatalkan' : record.result === 'GO' ? 'GO · Layak + Approved' : record.status === 'PENDING' ? 'Menunggu approval Coordinator' : 'NO GO' }}</span><p class="mt-2 text-xs font-semibold text-slate-600">Keputusan driver: {{ record.driver_decision === 'LAIK' ? 'Layak' : 'Tidak Layak' }} · Review: {{ record.status }}</p><p v-if="record.reviewer_name" class="mt-1 text-xs text-slate-500">{{ record.reviewer_name }} · {{ date(record.reviewed_at) }}</p><p v-if="record.rejection_reason" class="mt-2 break-words text-sm text-red-700">Alasan: {{ record.rejection_reason }}</p></div><div class="flex w-full flex-wrap gap-2 sm:w-auto"><a :href="`/go-no-go/${record.id}/download`" class="btn-ghost min-h-11 text-sm">Download Form</a><button type="button" class="btn-ghost min-h-11 text-sm" :aria-expanded="expanded" @click="expanded = !expanded">{{ expanded ? 'Tutup Detail' : 'Lihat Detail' }}</button></div></header>
        <div v-if="expanded" class="mt-4 min-w-0 border-t border-slate-100 pt-4">
            <dl class="grid min-w-0 gap-3 text-sm sm:grid-cols-2"><div><dt class="text-xs text-slate-500">Departemen / Jabatan</dt><dd class="mt-1 font-semibold">{{ record.department }} / {{ record.position }}</dd></div><div><dt class="text-xs text-slate-500">Lokasi Tujuan</dt><dd class="mt-1 font-semibold">{{ record.destination }}</dd></div><div><dt class="text-xs text-slate-500">No Pol Unit Dikawal</dt><dd class="mt-1 break-words">{{ plates }}</dd></div><div><dt class="text-xs text-slate-500">Nama Driver Dikawal</dt><dd class="mt-1 break-words">{{ names }}</dd></div></dl>
            <div class="mt-4 max-w-full overflow-x-auto" tabindex="0" role="region" aria-label="Checklist GO/NO GO"><table class="w-full min-w-[600px] text-left text-sm"><thead><tr class="border-b"><th scope="col" class="p-2">Item Pemeriksaan</th><th scope="col" class="p-2">Kondisi</th><th scope="col" class="p-2">Bukti / Referensi</th><th scope="col" class="p-2">Keterangan</th></tr></thead><tbody><tr v-for="(label, index) in checklist" :key="index" class="border-b border-slate-100"><td class="p-2">{{ index + 1 }}. {{ label }}</td><td class="p-2 font-semibold">{{ record.items[index]?.condition || '-' }}</td><td class="p-2">{{ record.items[index]?.evidence || '-' }}</td><td class="p-2">{{ record.items[index]?.note || '-' }}</td></tr></tbody></table></div>
            <p class="mt-3 whitespace-pre-wrap break-words text-sm"><b>Catatan driver:</b> {{ record.notes || '-' }}</p>
            <a :href="`/go-no-go/${record.id}/photo`" target="_blank" rel="noopener noreferrer" class="mt-3 inline-block text-sm font-bold text-red-700 underline">Buka Foto P5M</a><img :src="`/go-no-go/${record.id}/photo`" loading="lazy" class="mt-3 max-h-72 w-full rounded-xl bg-slate-50 object-contain" alt="Foto P5M pengajuan GO/NO GO">
            <div v-if="review && record.status === 'PENDING'" class="mt-4 flex flex-wrap gap-2"><button type="button" class="btn" @click="choose('APPROVED')">Setujui Pemeriksaan</button><button type="button" class="btn-ghost text-red-700" @click="choose('REJECTED')">Kembalikan / Tolak</button></div>
        </div>
        <form v-if="reviewAction && record.status === 'PENDING'" class="mt-4 rounded-xl bg-slate-50 p-4" @submit.prevent="submitReview"><p class="text-sm font-bold">{{ reviewAction === 'APPROVED' ? 'Konfirmasi persetujuan pemeriksaan?' : 'Kembalikan pemeriksaan untuk diperbaiki?' }}</p><p v-if="reviewAction === 'APPROVED' && record.driver_decision === 'TIDAK_LAIK'" class="mt-2 text-sm font-semibold text-red-800">Keputusan driver Tidak Layak. Hasil tetap NO GO dan escort tetap diblokir.</p><label v-if="reviewAction === 'REJECTED'" class="mt-3 block text-sm font-semibold">Alasan *<textarea v-model="reviewForm.reason" class="field" required maxlength="1000"></textarea></label><p v-for="(message, field) in reviewForm.errors" :key="field" class="err mt-2">{{ message }}</p><div class="mt-3 flex flex-wrap gap-2"><button class="btn" :disabled="reviewForm.processing">{{ reviewForm.processing ? 'Menyimpan...' : 'Konfirmasi' }}</button><button type="button" class="btn-ghost" :disabled="reviewForm.processing" @click="reviewAction = null">Batal</button></div></form>
        <div v-if="driver" class="mt-4 flex flex-wrap gap-2"><button v-if="canStart" type="button" class="btn" :disabled="startForm.processing" @click="start">Mulai Escort</button><button v-if="canRevise" type="button" class="btn-ghost" @click="emit('revise', record)">Ajukan Ulang</button><button v-if="!record.started_at && ['PENDING', 'APPROVED'].includes(record.status)" type="button" class="btn-ghost text-red-700" @click="cancelPrompt = !cancelPrompt">Batalkan Pengajuan</button></div>
        <div v-if="cancelPrompt" class="mt-3 rounded-xl border border-red-200 bg-red-50 p-3"><p class="text-sm text-red-800">Batalkan pengajuan dan lepaskan seluruh unit agar dapat dipilih kembali?</p><div class="mt-3 flex flex-wrap gap-2"><button type="button" class="btn" :disabled="cancelForm.processing" @click="cancel">Ya, Batalkan</button><button type="button" class="btn-ghost" @click="cancelPrompt = false">Kembali</button></div></div>
        <p v-for="(message, field) in { ...startForm.errors, ...cancelForm.errors }" :key="field" class="err mt-2">{{ message }}</p>
    </article>
</template>
